/* ---- app3.js ---- */
/* ===== app3: program map (offscreen base layer + per-frame overlay), hit testing, zoom/pan, minimap, search, lens ===== */
const S = { pid: null, c: null, build: null, sel: -1, hover: -1, colorBy: 'state', fState: new Set(), fTier: new Set(), fSite: false, view: 'map', product: null, hits: [], flashes: [] };
